def create_permanent_on_battlefield(game, player, card_name):
    """Create a permanent in HAND then move to battlefield via ZONE_CHANGE so
    interceptors register exactly once."""
    card_def = STUDIO_GHIBLI_CARDS[card_name]
    obj = game.create_object(
        name=card_name,
        owner_id=player.id,
        zone=ZoneType.HAND,
        characteristics=card_def.characteristics,
        card_def=None,
    )
    obj.card_def = card_def
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            'object_id': obj.id,
            'from_zone': f'hand_{player.id}',
            'to_zone': 'battlefield',
            'to_zone_type': ZoneType.BATTLEFIELD,
        },
    ))
    return obj


def assert_emit_or_register(game, expected, card_name):
    if expected:
        got_types = {e.type.name for e in game.state.event_log}
        if not any(et in got_types for et in expected):
            raise AssertionError(
                f"expected one of {expected} in event_log, got {sorted(got_types - {'ZONE_CHANGE'})}"
            )
    else:
        ids = [iid for iid in game.state.interceptors]
        assert ids, f"no interceptors registered for {card_name}"


