def test_card_forest_s_blessing():
    """Forest's Blessing: expects [] (spell with setup_interceptors)"""
    game = Game()
    p1 = game.add_player("Alice")
    p2 = game.add_player("Bob")
    card_def = STUDIO_GHIBLI_CARDS["Forest's Blessing"]
    # Spells with setup_interceptors (alt-cast mechanics): put in graveyard
    # so the setup runs there. Many register on cast or in graveyard.
    obj = game.create_object(
        name="Forest's Blessing",
        owner_id=p1.id,
        zone=ZoneType.HAND,
        characteristics=card_def.characteristics,
        card_def=None,
    )
    obj.card_def = card_def
    # Try graveyard zone first
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            'object_id': obj.id,
            'from_zone': f'hand_{p1.id}',
            'to_zone': f'graveyard_{p1.id}',
            'to_zone_type': ZoneType.GRAVEYARD,
        },
    ))
    expected = []
    if expected:
        got_types = {e.type.name for e in game.state.event_log}
        if not any(et in got_types for et in expected):
            # Weaker assertion: at least the interceptor must register
            ids = [iid for iid in game.state.interceptors]
            assert ids, f"no interceptors registered and no expected events for {card_def.name!r}"
    else:
        ids = [iid for iid in game.state.interceptors]
        assert ids, f"no interceptors registered for {card_def.name!r}"

