def test_card_curse_breaker():
    """Curse Breaker: expects ['LIFE_CHANGE'] (spell with resolve)"""
    game = Game()
    p1 = game.add_player("Alice")
    p2 = game.add_player("Bob")
    card_def = STUDIO_GHIBLI_CARDS['Curse Breaker']
    try:
        events = card_def.resolve(None, game.state) or []
    except Exception as e:
        raise AssertionError(f"resolve raised: {type(e).__name__}: {e}")
    expected = ['LIFE_CHANGE']
    if expected:
        got_types = {e.type.name for e in events}
        if not any(et in got_types for et in expected):
            raise AssertionError(
                f"expected one of {expected} in returned events, got {sorted(got_types)}"
            )
    else:
        assert len(events) > 0, "resolve emitted no events"

